  // Check if the response is header-only
  if (sent_header) {
    // Handle header-only response
    return;
  }

  // Check if the response is a custom HTTP response
  if (custom_http_ret) {
    // Set the request state error and dump the error code
    set_req_state_err(s, 0);
    dump_errno(s, custom_http_ret);
    return;
  }

  // Set the request state error and dump the error code
  set_req_state_err(s, (partial_content && !op_ret) ? STATUS_PARTIAL_CONTENT : op_ret);
